  ('obergurgl-hochgurgl-austria', '01F', 'Obergurgl-Hochgurgl', 'Austria', 'The Diamond of the Alps', 'live', 'verified', 'northernLights', 'Austria', '{"ski","family","adventure","wellness","culinary","culture","romance"}', '{"alpine","secluded","refined"}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Obergurgl = highest parish village in Austria (~1,930 m); Hochgurgl higher; inner Otztal, Tirol (municipality of Solden); ~400 residents","''Diamond of the Alps'' brand; among the most snow-sure resorts in the Alps (~475 cm avg snowfall); top-rated for snow reliability + family","Linked area ~112.2 km (60.2 easy / 33.2 int / 18.8 diff) + 4.5 km ski routes; 25 lifts; base ~1,793 m to ~3,030 m (vertical ~1,237 m); season mid-Nov-late April","Top of area ~3,030 m (skiresort) / ~3,080 m Wurmkogl (snow-forecast) - reconcile exact","The calm, upscale, snow-sure counterpart to Solden (same Otztal valley, distinct resort - Solden passed en route)","TOP Hotel Hochgurgl = luxury flagship: TWO Michelin KEYS (2024 & 2025) = HOTEL award NOT restaurant star; Falstaff Best of Austria 2024; TOP Mountain Spa >1,300 m2 (explicit 5-star wording to confirm)","Piccard''s 1931 stratosphere-balloon landing on the nearby Gurgler Ferner glacier - genuine heritage hook","Obergurgl parish church (1737, extended 1967 by Clemens Holzmeister)","Day pass ~EUR 77; Otztal Superskicard (links Solden + smaller Otztal areas); no confirmed Ikon/Epic","Reached via Otztal Bahnhof + valley bus up the Otztal past Solden; Innsbruck nearest airport","Heli-skiing NOT available (Austria permits it only at Vorarlberg/Lech-Zurs sites)","Avalanche = Lawinenwarndienst Tirol via Euregio lawinen.report, EAWS 5-level - NOT SLF/Meteo","Altitude is a genuine factor (village ~1,930 m, lifts ~3,030 m) - AMS/cold care for sea-level guests","Deep-snow expert side too (~18.8 km black + 4.5 km ski routes, 3,000 m terrain) despite the family reputation","Nearest hospital = Zams/Landeck area or Innsbruck University Hospital (verify); Solden has a village medical centre","Independent ski-test rating: 4.5 stars / ''Outstanding'' (snow reliability, expert terrain, family, gastronomy)","Two linked sub-villages: Obergurgl (the parish village) + Hochgurgl (higher, snowier, further up the valley)","TOP Mountain Spa exceeds 1,300 m2 - panoramic pools, saunas, steam bath and private spa suites","Falstaff ''Best of Austria 2024'' recognition for the TOP Hotel Hochgurgl","~475.5 cm average annual snowfall underpins the ''guaranteed-snow'' positioning","18.8 km of black piste + 4.5 km ski routes give a genuine expert side beneath the family reputation","Positioned as the quiet-luxury alternative to Solden''s bigger network and party scene"],"safety":{"emergency":"112 EU general / 140 Bergrettung alpine rescue / 144 ambulance / 133 police / 122 fire","hospital":"down-valley Zams/Landeck area or Innsbruck University Hospital; Solden village medical centre; 140 Bergrettung / helicopter alpine evac","malaria":"none","yellow_fever":"not required","activity_note":"Family pistes but 3,000 m off-piste + ski routes carry avalanche risk: Lawinenwarndienst Tirol via lawinen.report, EAWS 5-level; transceiver/shovel/probe + guide off-piste; genuine ALTITUDE (village ~1,930 m, lifts ~3,030 m) - AMS/cold care; heli NOT available (Austria = Vorarlberg); rescue 140 Bergrettung","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/austria","read":"2026-08-20T14:48:12Z","page_updated":"2026-08-11T10:19:06+01:00","source_country":"austria","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"High winter — Christmas/NY, Feb half-terms, Easter — plus a strong early-season (late Nov/Dec) snow-certainty window","shoulder":"Early Dec reliable opening + spring skiing (high snow into late April)","green":"May-Jun + Oct-Nov (primarily a winter resort - verify summer ops)","booking_lead":"Christmas/NY + Feb + Easter + TOP Hotel Hochgurgl 3-8 mo; regular winter 2-4 mo","off_season_specials":"Early-season snow-certainty window; spring-ski value; luxury-wellness stays","event_peaks":"Ski holidays (mid-Nov-late April), Christmas/NY, Easter (verify live events calendar)","fire_date":"Next winter + family + early-season snow-certainty by Jun-Sep; spring-ski from Jan; lead with guaranteed-snow angle"},"jewels":[{"name":"Ski the snow-sure ''Diamond of the Alps'' - ~112 km","si_tag":"Winter/Ski","status":"live","tier":"comfort","price_band":"~EUR 77/day pass; instructor ~EUR 350-550/day (approx)","timing":"ski ~mid-Nov-late April; verify","draw_rank":1,"si":"ski","when":"ski ~mid-Nov-late April; verify","commission":"school/operator 10-15%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ski"],"shelf_fit":{"adventure":"destination","culinary":"destination","culture":"destination","family":"destination","romance":"destination","ski":"primary","wellness":"destination"},"commission_pct_low":10,"commission_pct_high":15,"commission_lane":["operator","school"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Ride to the Wurmkogl (~3,030 m)","si_tag":"Winter/Ski","status":"live","tier":"comfort","price_band":"~EUR 77/day pass (approx)","timing":"High winter — Christmas/NY, Feb half-terms, Easter — plus a strong early-season  snow-certainty window","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the Hochgurgl top station reaches ~3,030 m for big, snow-holding terrain and a panoramic Top Mountain viewpoint — the high roof of the area","si":"ski","blurb":"the Hochgurgl top station reaches ~3,030 m for big, snow-holding terrain and a panoramic Top Mountain viewpoint — the high roof of the area","when":"High winter — Christmas/NY, Feb half-terms, Easter — plus a strong early-season  snow-certainty window","commission":"operator 10-15%","well